# Synthetic LEF/DEF layer map for the two-mask fixture: every purpose on M1 and M2 has an
# unmasked target (datatype 0) and one per mask (datatypes 1, 2).
M1 NET,SPNET,PIN,VIA,LEFPIN 10 0
M1 NET:MASK:1,SPNET:MASK:1,PIN:MASK:1,VIA:MASK:1,LEFPIN:MASK:1 10 1
M1 NET:MASK:2,SPNET:MASK:2,PIN:MASK:2,VIA:MASK:2,LEFPIN:MASK:2 10 2
M2 NET,SPNET,PIN,VIA,LEFPIN 20 0
M2 NET:MASK:1,SPNET:MASK:1,PIN:MASK:1,VIA:MASK:1,LEFPIN:MASK:1 20 1
M2 NET:MASK:2,SPNET:MASK:2,PIN:MASK:2,VIA:MASK:2,LEFPIN:MASK:2 20 2
V1 VIA 15 0
V2 VIA 25 0
M3 NET,SPNET,PIN,VIA 30 0
NAME M1/LABEL 10 10
NAME M2/LABEL 20 10
DIEAREA ALL 100 0
